from collections import deque
def is_bipartite(adj, n):
    colors = [-1] * n
    for start in range(n):
        if colors[start] == -1:
            queue = deque([start])
            colors[start] = 0
            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if colors[v] == -1:
                        colors[v] = 1 - colors[u]
                        queue.append(v)
                    elif colors[v] == colors[u]:
                        return False
    return True

